typedef struct {
    int u, v, w;
} Edge;

typedef struct {
    int to, w, next;
} Adj;

Adj adj[2 * MAXM];
int head[MAXN];
int adj_cnt = 0;

Edge edges[MAXM];
int n, m;

long long dist[MAXN];
int heap[MAXN];
int pos[MAXN];
int heap_size;

void add_edge(int u, int v, int w) {
    adj[adj_cnt].to = v;
    adj[adj_cnt].w = w;
    adj[adj_cnt].next = head[u];
    head[u] = adj_cnt++;
}

void swap(int i, int j) {
    int tmp = heap[i];
    heap[i] = heap[j];
    heap[j] = tmp;
    pos[heap[i]] = i;
    pos[heap[j]] = j;
}

void heapify_down(int idx) {
    int smallest = idx;
    int left = 2 * idx + 1;
    int right = 2 * idx + 2;
    if (left < heap_size && dist[heap[left]] < dist[heap[smallest]])
        smallest = left;
    if (right < heap_size && dist[heap[right]] < dist[heap[smallest]])
        smallest = right;
    if (smallest != idx) {
        swap(idx, smallest);
        heapify_down(smallest);
    }
}

void heapify_up(int idx) {
    while (idx > 0 && dist[heap[idx]] < dist[heap[(idx - 1) / 2]]) {
        swap(idx, (idx - 1) / 2);
        idx = (idx - 1) / 2;
    }
}

void push(int v) {
    heap[heap_size] = v;
    pos[v] = heap_size;
    heapify_up(heap_size);
    heap_size++;
}

int pop() {
    int v = heap[0];
    heap_size--;
    heap[0] = heap[heap_size];
    pos[heap[0]] = 0;
    heapify_down(0);
    return v;
}

int in_heap(int v) {
    return pos[v] < heap_size;
}

void dijkstra(int src) {
    for (int i = 0; i < n; i++) {
        dist[i] = LLONG_MAX;
        pos[i] = -1;
    }
    dist[src] = 0;
    heap_size = 0;
    push(src);
    while (heap_size > 0) {
        int u = pop();
        for (int i = head[u]; i != -1; i = adj[i].next) {
            int v = adj[i].to;
            int w = adj[i].w;
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                if (in_heap(v))
                    heapify_up(pos[v]);
                else
                    push(v);
            }
        }
    }
}

int parent[MAXN];

int find(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

void unite(int x, int y) {
    int rx = find(x);
    int ry = find(y);
    if (rx != ry) parent[ry] = rx;
}

int cmp(const void *a, const void *b) {
    return ((Edge*)a)->w - ((Edge*)b)->w;
}

