        edges[i].w = w;
        add_edge(u-1, v-1, w);
        add_edge(v-1, u-1, w);
    }

    dijkstra(0);

    // Filter edges that are on some shortest path
    Edge candidates[MAXM];
    int cand_cnt = 0;
    for (int i = 0; i < m; i++) {
        int u = edges[i].u;
        int v = edges[i].v;
        int w = edges[i].w;
        if (dist[u] + w == dist[v] || dist[v] + w == dist[u]) {
            candidates[cand_cnt++] = edges[i];
        }
    }

    qsort(candidates, cand_cnt, sizeof(Edge), cmp);

    for (int i = 0; i < n; i++) parent[i] = i;

    long long total_cost = 0;
    int components = n;
    for (int i = 0; i < cand_cnt && components > 1; i++) {
