typedef long long ll;

typedef struct Edge {
    int to;
    int w;
    int next;
} Edge;

typedef struct HeapNode {
    ll dist;
    int v;
} HeapNode;

static int cmp_ll(ll a, ll b) {
    return (a > b) - (a < b);
}

/* ---------- Min Heap for Dijkstra ---------- */
typedef struct MinHeap {
    HeapNode *a;
    int sz;
    int cap;
} MinHeap;

void heap_init(MinHeap *h, int cap) {
    h->a = (HeapNode *)malloc(sizeof(HeapNode) * (cap + 5));
    h->sz = 0;
    h->cap = cap + 5;
}

void heap_push(MinHeap *h, ll dist, int v) {
    if (h->sz + 1 >= h->cap) {
        h->cap <<= 1;
        h->a = (HeapNode *)realloc(h->a, sizeof(HeapNode) * h->cap);
    }
    int i = ++h->sz;
    h->a[i].dist = dist;
    h->a[i].v = v;
    while (i > 1) {
        int p = i >> 1;
        if (h->a[p].dist <= h->a[i].dist) break;
        HeapNode t = h->a[p];
        h->a[p] = h->a[i];
        h->a[i] = t;
        i = p;
    }
}

HeapNode heap_pop(MinHeap *h) {
    HeapNode ret = h->a[1];
    h->a[1] = h->a[h->sz--];
    int i = 1;
    while (1) {
        int l = i << 1, r = l + 1, s = i;
        if (l <= h->sz && h->a[l].dist < h->a[s].dist) s = l;
        if (r <= h->sz && h->a[r].dist < h->a[s].dist) s = r;
        if (s == i) break;
        HeapNode t = h->a[i];
        h->a[i] = h->a[s];
        h->a[s] = t;
        i = s;
    }
    return ret;
}

int heap_empty(MinHeap *h) {
    return h->sz == 0;
}

