int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    int *head = (int *)malloc((n + 1) * sizeof(int));
    for (int i = 1; i <= n; i++) head[i] = -1;

    Edge *edges = (Edge *)malloc((2LL * m + 5) * sizeof(Edge));
    int ecnt = 0;

    for (int i = 0; i < m; i++) {
        int u, v, w;
        scanf("%d %d %d", &u, &v, &w);

        edges[ecnt].to = v;
        edges[ecnt].w = w;
        edges[ecnt].next = head[u];
        head[u] = ecnt++;

        edges[ecnt].to = u;
        edges[ecnt].w = w;
        edges[ecnt].next = head[v];
        head[v] = ecnt++;
    }

    /* Dijkstra from capital 1 */
    ll INF = (ll)4e18;
    ll *dist = (ll *)malloc((n + 1) * sizeof(ll));
    for (int i = 1; i <= n; i++) dist[i] = INF;
    dist[1] = 0;

    MinHeap heap;
    heap_init(&heap, m + 5);
    heap_push(&heap, 0, 1);

    while (!heap_empty(&heap)) {
        HeapNode cur = heap_pop(&heap);
        ll d = cur.dist;
        int u = cur.v;
        if (d != dist[u]) continue;

        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            ll nd = d + edges[e].w;
            if (nd < dist[v]) {
                dist[v] = nd;
                heap_push(&heap, nd, v);
            }
        }
    }

    /*
      To preserve shortest distances, for every vertex v != 1
      we need one edge (u,v,w) such that dist[u] + w = dist[v].
      Among all such possible predecessor edges, choose minimum w.
      Sum over all vertices.
    */
    ll answer = 0;
    for (int v = 2; v <= n; v++) {
        int best = INT_MAX;
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int u = edges[e].to;
            int w = edges[e].w;
            if (dist[u] + w == dist[v]) {
                if (w < best) best = w;
            }
        }
        answer += best;
    }

    printf("%lld\n", answer);

    free(head);
    free(edges);
    free(dist);
    free(heap.a);
    return 0;
}

