public class KingMercerRoads {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();

        List<List<int[]>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        int[][] edges = new int[m][3];
        for (int i = 0; i < m; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            int c = sc.nextInt();
            edges[i][0] = u;
            edges[i][1] = v;
            edges[i][2] = c;
            graph.get(u).add(new int[]{v, c});
            graph.get(v).add(new int[]{u, c});
        }

        // Dijkstra from capital (0)
        long[] dist = new long[n];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[0] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[1]));
        pq.offer(new long[]{0, 0});

        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            int u = (int) cur[0];
            long d = cur[1];
            if (d != dist[u]) continue;
            for (int[] next : graph.get(u)) {
                int v = next[0];
                long nd = d + next[1];
                if (nd < dist[v]) {
                    dist[v] = nd;
                    pq.offer(new long[]{v, nd});
                }
            }
        }

        // For each node (except capital), pick cheapest edge that lies on a shortest path
        long totalCost = 0;
        for (int v = 1; v < n; v++) {
            long minCost = Long.MAX_VALUE;
            for (int[] edge : graph.get(v)) {
                int u = edge[0];
                long cost = edge[1];
                if (dist[u] + cost == dist[v]) {
                    minCost = Math.min(minCost, cost);
                }
            }
            totalCost += minCost;
        }

        System.out.println(totalCost);
    }
}

