/*
We need a minimum-cost subgraph such that:
1) All cities are connected to the capital.
2) The shortest distance from the capital to every city stays the same as in the original graph.

Key fact:
For every city v != capital, in any valid plan there must be at least one chosen edge (u, v)
such that dist[u] + w(u,v) = dist[v]. Otherwise v cannot be reached with its original shortest distance.

To minimize total cost while keeping connectivity, it is enough to choose for each v != capital
one cheapest edge among all edges that can be the last edge of a shortest path to v.
Then every node has a parent leading to smaller/equal shortest-distance predecessor chain back to capital,
so all chosen edges connect all cities and preserve distances.

Algorithm:
- Run Dijkstra from capital 1 to get shortest distances dist[].
- For each edge (a,b,w):
    if dist[a] + w == dist[b], then this edge can be a parent edge for b; minimize answer contribution for b.
    if dist[b] + w == dist[a], then this edge can be a parent edge for a; minimize answer contribution for a.
- Sum the chosen minimum incoming shortest-path edge cost for all vertices except capital.

Complexities:
- Dijkstra: O((n+m) log n)
- Scan edges: O(m)

This is the standard solution for "reduce to shortest path DAG and pick minimum incoming edge for each node".
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Edge {
        int to;
        long w;
        Edge(int to, long w) {
            this.to = to;
            this.w = w;
        }
    }

    static class FullEdge {
        int u, v;
        long w;
        FullEdge(int u, int v, long w) {
            this.u = u;
            this.v = v;
            this.w = w;
        }
    }

    static class Node implements Comparable<Node> {
        int v;
        long d;
        Node(int v, long d) {
            this.v = v;
            this.d = d;
        }
        public int compareTo(Node o) {
            return Long.compare(this.d, o.d);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int m = fs.nextInt();

        List<Edge>[] g = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) g[i] = new ArrayList<>();

        FullEdge[] edges = new FullEdge[m];
        for (int i = 0; i < m; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            long w = fs.nextLong();
            edges[i] = new FullEdge(u, v, w);
            g[u].add(new Edge(v, w));
            g[v].add(new Edge(u, w));
        }

        long INF = Long.MAX_VALUE / 4;
        long[] dist = new long[n + 1];
        Arrays.fill(dist, INF);
        dist[1] = 0;

        PriorityQueue<Node> pq = new PriorityQueue<>();
        pq.add(new Node(1, 0));

        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            if (cur.d != dist[cur.v]) continue;

            for (Edge e : g[cur.v]) {
                long nd = cur.d + e.w;
                if (nd < dist[e.to]) {
                    dist[e.to] = nd;
                    pq.add(new Node(e.to, nd));
                }
            }
        }

        long[] best = new long[n + 1];
        Arrays.fill(best, INF);

        for (FullEdge e : edges) {
            int u = e.u, v = e.v;
            long w = e.w;

            if (dist[u] + w == dist[v]) {
                if (w < best[v]) best[v] = w;
            }
            if (dist[v] + w == dist[u]) {
                if (w < best[u]) best[u] = w;
            }
        }

        long ans = 0;
        for (int i = 2; i <= n; i++) {
            ans += best[i];
        }

        System.out.println(ans);
    }
}
